/**
 * Why does this file exist? It is the fixed track network's arc-length arithmetic (native/routing, the WebAssembly core routingWasm.ts loads; tracks.ts stays the reference), compiled to WebAssembly
 * and carried here as base64 so the single-file build needs no cargo and no loader: 13163 bytes, SHA-256
 * 2758b798c4bd7320eb4104ba8d81b6660253fea15659cbb1dc481b9a71c8e088.
 * GENERATED by tools/native/build-wasm.mjs (npm run native:wasm) from native/routing; do not edit by hand.
 * What breaks if it is removed? routingWasm.ts has no module to instantiate: the fleet runs the TypeScript reference alone.
 */
export const ROUTING_WASM_BYTES = 13163
export const ROUTING_WASM_SHA256 = '2758b798c4bd7320eb4104ba8d81b6660253fea15659cbb1dc481b9a71c8e088'
export const ROUTING_WASM_BASE64 =
  ''
